-- WAVEY media seed for MAIN DB matched contents only
-- Contents INSERT omitted. JOINs existing contents on (title_ko, category).
-- Aliases: 스트레이 키즈→스트레이키즈, 리틀 포레스트→리틀포레스트
-- Rows: videos=126, albums=33, tracks=225
BEGIN;

CREATE TEMP TABLE wavey_seed_videos (
    category text NOT NULL, title_ko text NOT NULL, youtube_video_id text NOT NULL,
    title text NOT NULL, channel_title text, thumbnail_url text NOT NULL,
    duration_sec integer NOT NULL, hidden boolean NOT NULL, fetched_at timestamp NOT NULL
) ON COMMIT DROP;

SELECT c.content_id, v.youtube_video_id, v.title, v.channel_title, v.thumbnail_url, v.duration_sec, v.hidden, v.fetched_at, now(), now()
FROM wavey_seed_videos v
JOIN contents c ON c.title_ko = v.title_ko AND c.category = v.category
ON CONFLICT (content_id, youtube_video_id) DO UPDATE SET
    title = EXCLUDED.title, channel_title = EXCLUDED.channel_title, thumbnail_url = EXCLUDED.thumbnail_url,
    duration_sec = EXCLUDED.duration_sec, hidden = EXCLUDED.hidden, fetched_at = EXCLUDED.fetched_at, updated_at = now();

CREATE TEMP TABLE wavey_seed_albums (
    category text NOT NULL, title_ko text NOT NULL, spotify_album_id text NOT NULL,
    title text NOT NULL, image_url text, spotify_url text, hidden boolean NOT NULL, fetched_at timestamp NOT NULL
) ON COMMIT DROP;

SELECT c.content_id, a.spotify_album_id, a.title, a.image_url, a.spotify_url, a.hidden, a.fetched_at, now(), now()
FROM wavey_seed_albums a
JOIN contents c ON c.title_ko = a.title_ko AND c.category = a.category
ON CONFLICT (content_id, spotify_album_id) DO UPDATE SET
    title = EXCLUDED.title, image_url = EXCLUDED.image_url, spotify_url = EXCLUDED.spotify_url,
    hidden = EXCLUDED.hidden, fetched_at = EXCLUDED.fetched_at, updated_at = now();

CREATE TEMP TABLE wavey_seed_tracks (
    category text NOT NULL, title_ko text NOT NULL, spotify_album_id text,
    spotify_track_id text NOT NULL, title text NOT NULL, artist_name text,
    image_url text, spotify_url text, duration_ms bigint, hidden boolean NOT NULL, fetched_at timestamp NOT NULL
) ON COMMIT DROP;

SELECT c.content_id, ca.content_album_id, t.spotify_track_id, t.title, t.artist_name, t.image_url, t.spotify_url, t.duration_ms, t.hidden, t.fetched_at, now(), now()
FROM wavey_seed_tracks t
JOIN contents c ON c.title_ko = t.title_ko AND c.category = t.category
LEFT JOIN content_albums ca ON ca.content_id = c.content_id AND ca.spotify_album_id = t.spotify_album_id
ON CONFLICT (content_id, spotify_track_id) DO UPDATE SET
    content_album_id = EXCLUDED.content_album_id, title = EXCLUDED.title, artist_name = EXCLUDED.artist_name,
    image_url = EXCLUDED.image_url, spotify_url = EXCLUDED.spotify_url, duration_ms = EXCLUDED.duration_ms,
    hidden = EXCLUDED.hidden, fetched_at = EXCLUDED.fetched_at, updated_at = now();

COMMIT;
